#!/usr/bin/env python3
"""Commit v1.5.7 bump + health marker to GitHub via backend API."""
import urllib.request
import json
import gzip
import base64
import time
import sys

# Read owner token
with open('/tmp/owner_token.txt', 'r') as f:
    token = f.read().strip()

API = 'https://api.ivxholding.com'

def gzip_b64(filepath):
    """Read file, gzip, base64 encode."""
    with open(filepath, 'rb') as f:
        raw = f.read()
    compressed = gzip.compress(raw, compresslevel=9)
    return base64.b64encode(compressed).decode('ascii')

# Files to commit
files_to_commit = [
    {
        'path': 'expo/app.config.ts',
        'content': gzip_b64('/home/user/rork-app/expo/app.config.ts'),
        'contentEncoding': 'gzip-base64'
    },
    {
        'path': 'expo/android/app/build.gradle',
        'content': gzip_b64('/home/user/rork-app/expo/android/app/build.gradle'),
        'contentEncoding': 'gzip-base64'
    },
    {
        'path': 'backend/hono.ts',
        'content': gzip_b64('/home/user/rork-app/backend/hono.ts'),
        'contentEncoding': 'gzip-base64'
    },
]

payload = {
    'action': 'github_commit_multi_file',
    'confirm': True,
    'confirmText': 'CONFIRM_IVX_GITHUB_WRITE',
    'input': {
        'files': files_to_commit,
        'commitMessage': 'release: APK v1.5.7 (versionCode 77) — V11 conversation fix + autonomous + IVX IA all live. Bump version, add apkReleaseV157 health marker.'
    }
}

data = json.dumps(payload).encode('utf-8')
req = urllib.request.Request(
    f'{API}/api/ivx/developer-deploy/action',
    data=data,
    headers={
        'Content-Type': 'application/json',
        'Authorization': f'Bearer {token}'
    },
    method='POST'
)

try:
    resp = urllib.request.urlopen(req, timeout=30)
    result = json.loads(resp.read())
    print(f'Commit result: {json.dumps(result, indent=2)[:2000]}')

    # Extract commit SHA
    commit_sha = result.get('commitSha') or result.get('sha') or result.get('input', {}).get('commitSha', '')
    if not commit_sha:
        # Try to find it in the response
        for key in ['commit', 'sha', 'commitSha', 'result']:
            if key in result:
                val = result[key]
                if isinstance(val, str) and len(val) >= 7:
                    commit_sha = val
                    break
                elif isinstance(val, dict):
                    commit_sha = val.get('sha', val.get('commitSha', ''))
                    if commit_sha:
                        break
    print(f'\nCommit SHA: {commit_sha}')
except urllib.error.HTTPError as e:
    body = e.read().decode('utf-8', errors='replace')
    print(f'HTTP Error {e.code}: {body[:2000]}')
    sys.exit(1)
except Exception as e:
    print(f'Error: {e}')
    sys.exit(1)

